from django.db import migrations, models


def preservar_capacidades(apps, schema_editor):
    Atividade = apps.get_model("core", "Atividade")
    for atividade in Atividade.objects.using(schema_editor.connection.alias).all():
        capacidades = {}
        for modalidade in ("presencial", "online"):
            total = sum(p.quantidade_max_participantes for p in atividade.programacoes.filter(modalidade=modalidade))
            ocupadas = atividade.inscricoes.filter(modalidade=modalidade).count()
            capacidades[modalidade] = max(total, ocupadas)
        atividade.vagas = capacidades["presencial"]
        atividade.vagas_online = capacidades["online"]
        atividade.save(update_fields=("vagas", "vagas_online"))


